// The activity panel's own messages, named `activityPanel…` (docs/i18n.md, "The app's own panels").

/** The language the panel's frame document speaks, English with no document. */
function currentLanguage(): string {
  return (typeof document === "undefined" ? "" : document.documentElement.lang) || "en";
}

export function activityPanelLinesLabel(): string {
  switch (currentLanguage()) {
    case "ar":
      return `أسطر النشاط`;
    case "de":
      return `Aktivitätszeilen`;
    case "es":
      return `Líneas de actividad`;
    case "fr":
      return `Lignes d’activité`;
    case "ja":
      return `アクティビティの行`;
    case "ko":
      return `활동 줄`;
    case "pt-BR":
      return `Linhas de atividade`;
    case "zh-Hans":
      return `动态条目`;
    case "zh-Hant":
      return `動態項目`;
    case "en-XA":
      return `[Åçţîṽîţý ļîñéš ~~~~~]`;
    case "ar-XB":
      return `\u202eActivity lines\u202c`;
  }
  return `Activity lines`;
}
